88	
89	      for (let i = 0; i < count; i++) {
90	        const nextWord = findNextWordAcrossLines(lines, endRow, endCol, true);
91	        if (nextWord) {
92	          endRow = nextWord.row;
93	          endCol = nextWord.col;
94	        } else {
95	          // No more words. Check if we can delete to the end of the current word.
96	          const currentLine = lines[endRow] || '';
97	          const wordEnd = findWordEndInLine(currentLine, endCol);
98	
99	          if (wordEnd !== null) {
100	            // Found word end, delete up to (and including) it
101	            endCol = wordEnd + 1;
102	          }
103	          // If wordEnd is null, we are likely on trailing whitespace, so do nothing.
104	          break;
105	        }
106	      }
107	
108	      if (endRow !== cursorRow || endCol !== cursorCol) {
109	        const nextState = detachExpandedPaste(pushUndo(state));
110	        return replaceRangeInternal(
111	          nextState,
112	          cursorRow,
113	          cursorCol,
114	          endRow,
115	          endCol,
116	          '',
117	        );
118	      }
119	      return state;
