/**
 * Toggle the case of a single character. Non-alphabetic characters are
 * returned unchanged. Uses locale-independent case conversion so it works
 * correctly with Unicode and multi-byte characters.
 */
function toggleCharCase(char: string): string {
  const lower = char.toLowerCase();
  const upper = char.toUpperCase();
  if (char === lower && char !== upper) {
    // Currently lowercase (and has an uppercase form) -> uppercase.
    return upper;
  }
  if (char === upper && char !== lower) {
    // Currently uppercase (and has a lowercase form) -> lowercase.
    return lower;
  }
  return char;
}

/**
