function findCharForward(
  line: string,
  cursorCol: number,
  char: string,
  count: number,
): number {
  const codePoints = toCodePoints(line);
  let remaining = count;
  for (let i = cursorCol + 1; i < codePoints.length; i++) {
    if (codePoints[i] === char) {
      remaining--;
      if (remaining === 0) {
        return i;
      }
    }
  }
  return -1;
}

